using System.Text.Json;
using System.Text;
int count=0;void Check(bool b,string name){if(!b)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
JsonElement J(object x)=>JsonSerializer.SerializeToElement(x);
object Item(int value)=>new{name="木材",value,craftingId="wood",nutrition=0,fuelHeat=1,fuelDuration=20,description=new string('x',10000)};
var raw=J(Enumerable.Range(0,18).Select(Item).ToArray());string before=raw.GetRawText();
var page=ToolResultProjection.Project("find_items",raw);
Check(page.GetProperty("data").GetArrayLength()==4,"18 entries capped to four");
Check(page.GetProperty("omitted").GetInt32()==14&&page.GetProperty("truncated").GetBoolean(),"omissions explicit");
Check(page.GetProperty("hasMore").ValueKind==JsonValueKind.Null,"native pagination unknown not invented");
Check(page.GetRawText().Length<3000,"huge descriptions bounded");
Check(raw.GetRawText()==before,"raw audit immutable");
var item=page.GetProperty("data")[0];foreach(var key in new[]{"name","value","craftingId","nutrition","fuelHeat","fuelDuration"})Check(item.TryGetProperty(key,out _),"item fact "+key);
Check(ToolResultProjection.Project("find_items",J(new{data=raw,hasMore=true})).GetProperty("hasMore").GetBoolean(),"native hasMore retained");
Check(ToolResultProjection.Project("find_items",J(new{unexpected=1})).GetProperty("projectionStatus").GetString()=="unsupported_shape","unknown query shape not empty success");
Check(ToolResultProjection.Project("read_item",J(new{name="partial"})).GetProperty("projectionStatus").GetString()=="unsupported_shape","partial item rejected");
var ingredients=new[]{new{column=0,row=0,craftingId="planks",data=(int?)null},new{column=1,row=0,craftingId="stick",data=(int?)null}};
var recipe=new{resultValue=122,resultCount=1,remainsValue=0,remainsCount=0,station=1,requiredHeat=0,requiredLevel=0,ingredients,description=new string('a',10000)};
var recipes=ToolResultProjection.Project("find_recipes",J(new[]{new{reference="r1",recipe}}));
Check(recipes.GetProperty("data")[0].GetProperty("reference").GetString()=="r1","recipe ref preserved");
Check(recipes.GetProperty("data")[0].GetProperty("recipe").GetProperty("ingredients").GetArrayLength()==2,"recipe ingredients complete");
var slots=new[]{new{slot=0,value=88,count=1},new{slot=1,value=0,count=0}};
var furnace=new{heat=1,progress=.5,fuelSecondsRemaining=10,fuelSlot=1,resultSlot=2,remainsSlot=3};
var storage=ToolResultProjection.Project("read_storage",J(new{inventory=new{slots},furnace,crafting=(object?)null}));
Check(storage.GetProperty("data").GetProperty("inventory").GetProperty("slots").GetArrayLength()==2,"empty and occupied slots preserved");
Check(storage.GetProperty("data").GetProperty("furnace").GetRawText()==J(furnace).GetRawText(),"furnace complete");
var huge=ToolResultProjection.Project("read_storage",J(new{inventory=new{slots,note=new string('a',8000)},furnace}));
Check(huge.GetProperty("projectionStatus").GetString()=="budget_exceeded"&&huge.GetProperty("data").ValueKind==JsonValueKind.Null,"oversized storage not partial success");
var context=ToolResultProjection.BuildContext(J(new{health=.8}),Enumerable.Repeat(page,18).ToArray(),1000,1000);
Check(context.GetRawText().Length<=1000&&Encoding.UTF8.GetByteCount(context.GetRawText())<=1000,"total context characters and bytes bounded");
Check(context.GetProperty("omittedRecent").GetInt32()>0,"context omissions explicit");
var fail=ToolResultProjection.BuildContext(J(new{note=new string('中',18000)}),[],1000,1000);
Check(fail.GetProperty("projectionStatus").GetString()=="facts_too_large","facts never silently truncated");
Check(ToolResultProjection.Project("read_item",J(new{ok=false,data=Item(1)})).GetProperty("projectionStatus").GetString()=="native_not_success","native failure not success");
Console.WriteLine("TOTAL "+count);
var map=JsonDocument.Parse("""{"entries":[{"reference":"old1","position":{"x":2,"y":65,"z":3},"lastSeenGameTime":2,"name":"old tree"}],"offset":0,"total":3,"hasMore":true,"nextOffset":1,"snapshotGameTime":10,"note":"historical live LRU, not stable snapshot"}""").RootElement.Clone();
var projectedMap=ToolResultProjection.Project("read_map",map);
Check(projectedMap.GetProperty("hasMore").GetBoolean(),"native map hasMore copied");
Check(projectedMap.GetProperty("data").GetProperty("nextOffset").GetInt32()==1,"map cursor not fabricated");
Check(projectedMap.GetProperty("data").GetProperty("entries")[0].GetProperty("lastSeenGameTime").GetInt32()==2,"historical observation time retained");
Check(projectedMap.GetProperty("data").GetProperty("note").GetString()!.Contains("not stable"),"live pagination caveat retained");
Check(ToolResultProjection.Project("read_map",J(new[]{new{reference="old"}})).GetProperty("projectionStatus").GetString()=="unsupported_shape","legacy unbounded map not falsely pageable");
var invalidMap=JsonDocument.Parse(map.GetRawText().Replace("\"nextOffset\":1","\"nextOffset\":2")).RootElement.Clone();
Check(ToolResultProjection.Project("read_map",invalidMap).GetProperty("projectionStatus").GetString()=="unsupported_shape","inconsistent next cursor rejected");
var oversizedMap=JsonDocument.Parse(map.GetRawText().Replace("old tree",new string('x',6000))).RootElement.Clone();
Check(ToolResultProjection.Project("read_map",oversizedMap).GetProperty("projectionStatus").GetString()=="budget_exceeded","large page not partial fictitious cursor");
Console.WriteLine("MAP FINAL TOTAL "+count);
var nav=J(new{request_id=Guid.NewGuid().ToString(),status="stopping",busy=true,reason="cancel_requested",segments=2,path=1.5,remaining=1.2});
var navProjected=ToolResultProjection.Project("host_navigation_status",nav);
Check(JsonElement.DeepEquals(navProjected.GetProperty("data"),nav),"navigation stopping status and progress retained exactly");
Check(ToolResultProjection.Project("host_navigation_status",J(new{request_id=Guid.Empty.ToString(),status="running",busy=true})).GetProperty("projectionStatus").GetString()=="unsupported_shape","busy without real request rejected");
var rejection=ToolResultProjection.Project("host_navigate_local",J(new{status="rejected",reason="navigation_busy"}));
Check(rejection.GetProperty("data").GetProperty("status").GetString()=="rejected","host navigation rejection not promoted to success");
var atomic=J(new{snapshotId=Guid.NewGuid(),visibleBlocks=new[]{new{reference="b1",value=9}},coverage=new{scanComplete=false,omittedBlocks=2},inventory=new{slots=new[]{new{slot=0,value=9,count=2}},selectedSlot=0},inventorySummary=new{nonEmptySlots=1}});
var split=ToolResultProjection.SplitObservation(atomic);
Check(JsonElement.DeepEquals(split.Inventory,atomic.GetProperty("inventory")),"same observation inventory retained exactly");
Check(JsonElement.DeepEquals(split.Observation.GetProperty("visibleBlocks"),atomic.GetProperty("visibleBlocks")),"split never trims visible references");
Check(JsonElement.DeepEquals(split.Observation.GetProperty("coverage"),atomic.GetProperty("coverage")),"split retains coverage limitations exactly");
Check(!split.Observation.TryGetProperty("inventory",out _)&&!split.Observation.TryGetProperty("inventorySummary",out _),"duplicate inventory omitted only from model observation view");
Check(atomic.TryGetProperty("inventory",out _),"raw observation audit is not mutated");
bool missingInventory=false;try{ToolResultProjection.SplitObservation(J(new{visibleBlocks=new object[0]}));}catch(ArgumentException){missingInventory=true;}
Check(missingInventory,"missing atomic inventory fails rather than doing later read");
Console.WriteLine("HOST FINAL TOTAL "+count);
var selfFacts=J(new{self=new{isMounted=(bool?)false,hasParentBody=(bool?)true,grounded=(bool?)false,immersion=(float?).4f},inventory=new{slots=Array.Empty<object>(),selectedSlot=(int?)null}});
var bodySplit=ToolResultProjection.SplitObservation(selfFacts).Observation.GetProperty("self");
Check(!bodySplit.GetProperty("isMounted").GetBoolean()&&bodySplit.GetProperty("hasParentBody").GetBoolean(),"split preserves independent mounted and parent facts");
Check(!bodySplit.GetProperty("grounded").GetBoolean()&&bodySplit.GetProperty("immersion").GetSingle()==.4f,"split preserves own support immersion");
var nullSelf=J(new{self=new{isMounted=(bool?)null,hasParentBody=(bool?)null,grounded=(bool?)null,immersion=(float?)null},inventory=new{slots=Array.Empty<object>(),selectedSlot=(int?)null}});
Check(ToolResultProjection.SplitObservation(nullSelf).Observation.GetProperty("self").GetProperty("isMounted").ValueKind==JsonValueKind.Null,"split never guesses unknown mounted false");
Console.WriteLine("BODY PROJECTION TOTAL "+count);

var blocks=Enumerable.Range(0,32).Select(i=>new{reference="reference_"+i,cell=new{x=i,y=64,z=1},position=new{x=i+.5,y=64.5,z=1.5},value=2,name="泥土",distance=(double)i,face=(int?)null}).ToArray();
var fullFacts=J(new{goal="retain refs",inventory=new{slots,selectedSlot=0},observation=new{snapshotId=Guid.NewGuid(),self=new{health=.7},visibleBlocks=blocks,pickables=new[]{new{reference="p1",sense="proximity",value=9,count=1},new{reference="p2",sense="vision",value=9,count=2}},entities=Array.Empty<object>(),coverage=new{scanComplete=false,budgetExhausted=true,visibleBlockTotal=40,returnedBlocks=32,omittedBlocks=8,entitiesTruncated=false,pickablesTruncated=true,objectRange=16,eye=new{x=1,y=2,z=3},note="Unseen is unknown"}}});
var compactFacts=ToolResultProjection.CompactPublicFacts(fullFacts);
Check(compactFacts.GetRawText().Length<fullFacts.GetRawText().Length,"lossless repeated field encoding saves context space");
Check(JsonElement.DeepEquals(ToolResultProjection.ExpandPublicFacts(compactFacts),fullFacts),"complete public fact round trip retains every value and reference");
Check(JsonElement.DeepEquals(compactFacts.GetProperty("observation").GetProperty("coverage"),fullFacts.GetProperty("observation").GetProperty("coverage")),"coverage unknown/truncated/range unchanged");
Check(JsonElement.DeepEquals(compactFacts.GetProperty("inventory"),fullFacts.GetProperty("inventory")),"inventory remains original structured facts");
Check(compactFacts.GetProperty("observation").GetProperty("visibleBlocks").GetProperty("rowCount").GetInt32()==32,"no visible blocks omitted by column encoding");
Check(JsonElement.DeepEquals(ToolResultProjection.CompactPublicFacts(compactFacts),compactFacts),"column encoding idempotent");
var smallBudget=compactFacts.GetRawText().Length+150;
var boundedFacts=ToolResultProjection.BuildContext(fullFacts,[],smallBudget,Math.Min(16000,smallBudget*2));
Check(boundedFacts.GetProperty("projectionStatus").GetString()=="projected","oversized raw facts fit after lossless encoding before rejection");
Check(boundedFacts.GetRawText().Length<=smallBudget,"encoded context obeys unchanged requested budget");
Check(JsonElement.DeepEquals(ToolResultProjection.ExpandPublicFacts(boundedFacts.GetProperty("facts")),fullFacts),"automatic budget path is lossless");
var heterogeneous=J(new{observation=new{visibleBlocks=new object[]{new{reference="a",face=(int?)null},new{reference="b"}}}});
Check(JsonElement.DeepEquals(ToolResultProjection.CompactPublicFacts(heterogeneous),heterogeneous),"missing versus explicit null field not conflated");
var realRaw=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"observation40-c.json"))).RootElement.Clone();
var realSplit=ToolResultProjection.SplitObservation(realRaw);
var realFacts=J(new{goal=new string('g',1200),observation=realSplit.Observation,inventory=realSplit.Inventory,host=new string('h',2500)});
var realContext=ToolResultProjection.BuildContext(realFacts,[],11000,12800);
Check(realFacts.GetRawText().Length>11000,"recorded post-Dig snapshot plus synthetic host overhead exceeds original budget");
Check(realContext.GetProperty("projectionStatus").GetString()=="projected","recorded post-Dig facts rescued within 11K budget");
Check(realContext.GetRawText().Length<=11000&&Encoding.UTF8.GetByteCount(realContext.GetRawText())<=12800,"real regression respects characters and UTF8 limits");
Check(JsonElement.DeepEquals(ToolResultProjection.ExpandPublicFacts(realContext.GetProperty("facts")),realFacts),"recorded public snapshot exact round trip no changed refs");
var invalidTable=JsonDocument.Parse("{\"observation\":{\"visibleBlocks\":{\"encoding\":\"lossless_columns_v1\",\"columns\":[\"reference\"],\"rows\":[[]],\"rowCount\":1}}}").RootElement.Clone();
bool rejectedTable=false;try{ToolResultProjection.ExpandPublicFacts(invalidTable);}catch(ArgumentException){rejectedTable=true;}Check(rejectedTable,"corrupt column row fails instead of guessing fields");
Console.WriteLine($"FACT SIZES raw={realFacts.GetRawText().Length} encodedContext={realContext.GetRawText().Length} utf8={Encoding.UTF8.GetByteCount(realContext.GetRawText())}");
Console.WriteLine("PUBLIC FACT FINAL TOTAL "+count);
